import tkinter as tk
import json

class ConfigParser:
    def __init__(self, filename):
        self.config = json.load(open(filename, 'r'))

    def get_button_config(self):
        return self.config.get('buttons', [])

    def get_label_config(self):
        return self.config.get('labels', [])

def generate_ui(config_parser):
    root = tk.Tk()
    root.title(""Custom UI"")

    for button_config in config_parser.get_button_config():
        btn = tk.Button(root, text=button_config['text'], width=button_config['width'], bg=button_config['bg'])
        btn.pack()

    for label_config in config_parser.get_label_config():
        lbl = tk.Label(root, text=label_config['text'], bg=label_config['bg'])
        lbl.pack()

    root.mainloop()

if __name__ == ""__main__"":
    parser = ConfigParser('config.json')
    generate_ui(parser)
