from flask import Flask
import yaml
from flask_sqlalchemy import SQLAlchemy
from functools import wraps
import jwt
from flask_jwt_extended import JWTManager

app = Flask(__name__)
app.config.from_pyfile('config.yaml')
db = SQLAlchemy(app)

class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    password = db.Column(db.String(120), nullable=False)

@app.route('/login', methods=['POST'])
def login():
    auth = request.json.get('auth')
    if not auth:
        return jsonify({'msg': 'Missing authentication'}), 401
    user = User.query.filter_by(username=auth['username']).first()
    if not user or not user.password == auth['password']:
        return jsonify({'msg': 'Invalid credentials'}), 401
    token = create_access_token(identity=user.username)
    return jsonify(access_token=token)

def token_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization')
        if not token:
            return jsonify({'msg': 'Missing authorization'}), 401
        try:
            data = jwt.decode(token, app.config['SECRET_KEY'], algorithms=['HS256'])
            current_user = User.query.filter_by(username=data).first()
            if not current_user:
                return jsonify({'msg': 'Invalid token'}), 401
        except:
            return jsonify({'msg': 'Invalid token'}), 401
        return f(*args, **kwargs)
    return decorated

jwt_manager = JWTManager(app)

@app.route('/protected', methods=['GET'])
@token_required
def protected():
    return jsonify({'msg': 'This is a protected route'})

if __name__ == '__main__':
    app.run()
