from collections import deque

class Queue:
    def __init__(self):
        self.queue = deque()

    def enqueue(self, item):
        self.queue.append(item)

    def dequeue(self):
        if not self.is_empty():
            return self.queue.popleft()
        else:
            raise ValueError(""Queue is empty"")

    def peek(self):
        if not self.is_empty():
            return self.queue[0]
        else:
            raise ValueError(""Queue is empty"")

    def is_empty(self):
        return len(self.queue) == 0

    def size(self):
        return len(self.queue)

    def __del__(self):
        pass
