import requests
import json
import threading

class WeatherStation:
    def __init__(self, name):
        self.name = name
        self.temperature = 0
        self.humidity = 0
        self.wind_speed = 0

    def update(self, temp, humidity, wind_speed):
        self.temperature = temp
        self.humidity = humidity
        self.wind_speed = wind_speed

def send_weather_data(weather_station):
    while True:
        try:
            payload = {
                ""station"": weather_station.name,
                ""temperature"": weather_station.temperature,
                ""humidity"": weather_station.humidity,
                ""wind_speed"": weather_station.wind_speed
            }
            response = requests.post('http://weather-server.com/update', json=payload)
            if response.status_code == 200:
                print(f""Data sent from {weather_station.name} to the server successfully."")
            else:
                print(f""Error sending data from {weather_station.name}: {response.text}"")
        except requests.exceptions.RequestException as e:
            print(f""An error occurred while sending data from {weather_station.name}: {e}"")

def main():
    weather_stations = [WeatherStation(""Station1""), WeatherStation(""Station2""), WeatherStation(""Station3"")]

    threads = []
    for station in weather_stations:
        thread = threading.Thread(target=send_weather_data, args=(station,))
        threads.append(thread)
        thread.start()

if __name__ == ""__main__"":
    main()
