import json

class JSONHandler:
    def __init__(self):
        self.registry = {}

    def add_factory(self, id, factory_function):
        self.registry[id] = factory_function

    def convert_to_json(self, data):
        return json.dumps(data)

    def convert_from_json(self, json_string):
        return json.loads(json_string)

    def create_instance(self, id):
        if id in self.registry:
            factory_function = self.registry[id]
            return factory_function()
        else:
            raise ValueError(f""No registered factory for ID {id}"")

class DataObjectFactory:
    @staticmethod
    def create():
        return DataObject()

class DataObject:
    pass

def main():
    handler = JSONHandler()

    # Adding factory functions to the registry
    handler.add_factory('data_object', DataObjectFactory.create)

    # Creating instances using the factory function associated with an ID
    instance = handler.create_instance('data_object')

    # Using instance to demonstrate conversion methods
    data = {'key': 'value'}

    # Converting data to JSON string
    json_str = handler.convert_to_json(data)

    # Converting JSON string back to an object using registry function
    restored_data = handler.convert_from_json(json_str)

if __name__ == ""__main__"":
    main()
