import csv
from statistics import mean

def calculate_average(csv_file_path: str, numeric_column_index: int) -> dict:
    try:
        with open(csv_file_path, 'r') as file:
            reader = csv.reader(file)

            # Check if the specified column exists in the CSV file
            headers = next(reader)
            if len(headers) <= numeric_column_index:
                raise ValueError(f""Column {numeric_column_index} not found in the CSV file."")

            values = [float(row[numeric_column_index]) for row in reader]
            average = mean(values)

            # Allow customization of output format (e.g., '.2f' for two decimal places)
            return {'average': f'{average:.2f}'}

    except FileNotFoundError:
        return {'error': f""File not found: {csv_file_path}""}
    except ValueError as e:
        return {'error': str(e)}
    except Exception as e:
        return {'error': 'An unexpected error occurred.'}']",99,[0],[],True,0,0,0,

