import pandas as pd
import numpy as np
from faker import Faker

fake = Faker()

def generate_random_data(table_name: str, num_entries: int, columns: dict):
    df = pd.DataFrame(columns=columns)

    for _ in range(num_entries):
        row = {}
        for column, type_ in columns.items():
            if type_ == 'str':
                row[column] = fake.text()
            elif type_ == 'int':
                row[column] = np.random.randint(0, 100)
            elif type_ == 'float':
                row[column] = np.random.rand()
            elif type_ == 'datetime':
                row[column] = pd.to_datetime('now')
        df = df.append(row, ignore_index=True)

    if 'unique_constraints' in columns:
        df['unique_constraint'] = df.apply(lambda x: ''.join(map(str, x)), axis=1)
        unique_values = set()
        for i in range(len(df)):
            while df.loc[i, 'unique_constraint'] in unique_values:
                df.loc[i, 'unique_constraint'] = fake.text()
            unique_values.add(df.loc[i, 'unique_constraint'])
    if 'indexes' in columns:
        df['index_column'] = np.random.randint(0, 100, size=len(df))

    return df

# Example usage
columns = {'id': str, 'name': str, 'age': int, 'email': str, 'date_of_birth': datetime}
