import json
import requests
import threading

class WeatherStation:
    def __init__(self, name):
        self.name = name

    def get_data(self):
        # simulate getting real-time weather data from a station
        return {
            ""temperature"": 25.5,
            ""humidity"": 60,
            ""wind_speed"": 10.2
        }

def send_data_to_server(station):
    data = json.dumps({""station_name"": station.name, **station.get_data()})
    try:
        response = requests.post(""http://example.com/weather_data"", data=data)
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        print(f""Error sending data from {station.name}: {e}"")

def main():
    stations = [WeatherStation(f""Station {i}"") for i in range(5)]

    threads = []
    for station in stations:
        t = threading.Thread(target=send_data_to_server, args=(station,))
        t.start()
        threads.append(t)

    for thread in threads:
        thread.join()

if __name__ == ""__main__"":
    main()
