import hashlib
import os
import json
import threading
import logging

logging.basicConfig(level=logging.INFO)

def compute_sha256_hash(text, encoding=""utf-8""):
    hash = hashlib.sha256()
    if encoding == ""utf-16"":
        text.encode(""utf-16"").__iter__()
    elif encoding == ""ascii"":
        text.encode(""ascii"").__iter__()
    hash.update(text.encode(encoding))
    return hash.hexdigest()

def compute_multiple_hashes(directory, encoding=""utf-8"", num_threads=4):
    hashes = {}
    def thread_func(directory):
        for file in os.listdir(directory):
            file_path = os.path.join(directory, file)
            if os.path.isfile(file_path):
                try:
                    with open(file_path, ""rb"") as f:
                        content = f.read()
                        hash = compute_sha256_hash(content.decode(encoding), encoding)
                        hashes[file] = hash
                except Exception as e:
                    logging.error(f""Error processing {file}: {e}"")
            elif os.path.isdir(file_path):
                thread_func(file_path)

    threads = []
    for _ in range(num_threads):
        t = threading.Thread(target=thread_func, args=(directory,))
        threads.append(t)
        t.start()

    for t in threads:
        t.join()

    return hashes

def compute_hashes_in_parallel(directory1, directory2, encoding=""utf-8"", num_threads=4):
    def thread_func(direc):
        hashes = {}
        for file in os.listdir(direc):
            file_path = os.path.join(direc, file)
            if os.path.isfile(file_path):
                try:
                    with open(file_path, ""rb"") as f:
                        content = f.read()
                        hash = compute_sha256_hash(content.decode(encoding), encoding)
                        hashes[file] = hash
                except Exception as e:
                    logging.error(f""Error processing {file}: {e}"")
            elif os.path.isdir(file_path):
                thread_func(file_path)

        return hashes

    threads = []
    t1 = threading.Thread(target=thread_func, args=(directory1,))
    t2 = threading.Thread(target=thread_func, args=(directory2,))
    threads.append(t1)
    threads.append(t2)
    for t in threads:
        t.start()
    for t in threads:
        t.join()

    return {directory1: t1.get(), directory2: t2.get()}

def main():
    # Option to save hashes to a file
    save_to_file = input(""Do you want to save the hash values to a file? (yes/no): "")
    if save_to_file.lower() == ""yes"":
