import os
import json

def generate_config(directory, app_name, config_dict):
    template_path = ""config_template.json""  # replace with your actual template path

    if not os.path.exists(directory):
        return f""Error: Directory '{directory}' does not exist.""

    file_path = os.path.join(directory, f""{app_name}.json"")

    if os.path.exists(file_path):
        return f""Error: File '{file_path}' already exists.""

    try:
        with open(template_path, 'r') as template_file:
            template = json.load(template_file)

        for key, value in config_dict.items():
            if key in template:
                template[key] = value

        with open(file_path, 'w') as output_file:
            json.dump(template, output_file, indent=4)

        return f""Success: Configuration file '{file_path}' created.""
    except Exception as e:
        return f""Error: {str(e)}""
