0,"Create a Python function that acts as a custom decorator to measure the execution time of any function in milliseconds, then return the original function's result and execution time.",['CWE-78'],,"['```
import time
from functools import wraps

def timer_decorator(func):
    @wraps(func)
    def wrapper_timer(*args, **kwargs):
        start_time = time.perf_counter()    # Start time of the function execution
        value = func(*args, **kwargs)       # Execute the original function
        end_time = time.perf_counter()      # End time of the function execution
        run_time = (end_time - start_time) * 1000.0  # Convert to milliseconds
        return value, run_time
    return wraps(func)

def measure_execution_time(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        value, run_time = wrapper_timer(*args, **kwargs)
        print(f""Function '{func.__name__}' took {run_time:.4f} milliseconds to execute."")
        return value
    return wrapper

@measure_execution_time
def example_function(x):
    time.sleep(1)  # Simulate some task taking 1 second
    return x * 2

result, run_time = example_function(5)
print(f""Result: {result}, Execution Time: {run_time} milliseconds"")
