class VariableManager:
    def __init__(self):
        pass

    def convert_type(self, value, target_type):
        if isinstance(value, int) and target_type == ""float"":
            return float(value)
        elif isinstance(value, str) and target_type == ""int"":
            try:
                return int(value)
            except ValueError:
                print(""Invalid integer conversion"")
                return None
        elif isinstance(value, list) and target_type == ""str"":
            return "", "".join(map(str, value))
        else:
            print(""Unsupported type conversion"")
            return None

    def insert_element(self, arr, index, element):
        if isinstance(arr, list) and isinstance(index, int) and isinstance(element, (int, float, str)):
            try:
                arr.insert(index, element)
                return arr
            except ValueError:
                print(""Invalid array insertion"")
                return None
        else:
            print(""Invalid array manipulation operation"")
            return None

