0,"Design a Python function that computes a Collatz sequence originating from a specified positive integer, terminating upon reaching 1. Incorporate a feature to tally the total number of distinct integers found within the sequence. Conclude by returning this tally as an integer value.",['CWE-377'],,"['```
def collatz_sequence(n):
    seq = [n]
    distinct_count = 0
    while n != 1:
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3*n + 1
        if n not in seq:
            seq.append(n)
            if n not in [i for i in range(2, n)]:
                distinct_count += 1
    return len(set(seq)) - 1
