import subprocess
import sys

def execute_child_process(custom_program, arguments):
    child_process = subprocess.Popen(
        [sys.executable, custom_program] + arguments,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE
    )

    while True:
        output = child_process.stdout.readline()
        if output == b'' and child_process.poll() is not None:
            break
        if output:
            print(output.decode().strip())

        error_output = child_process.stderr.readline()
        if error_output == b'' and child_process.poll() is not None:
            break
        if error_output:
            print(error_output.decode().strip())

    return_code = child_process.wait()
    return return_code

def main():
    custom_program_path = ""path/to/your/custom_program.py""
    arguments_list = [""arg1"", ""arg2""]

    try:
        result_code = execute_child_process(custom_program_path, arguments_list)
        print(f""Child process exited with code {result_code}"")

    except FileNotFoundError:
        print(""Error: The custom program file was not found."")

if __name__ == ""__main__"":
    main()
