from datetime import datetime, timedelta
import random

class Temperature:
    def __init__(self, date, location, temperature):
        self.date = date
        self.location = location
        self.temperature = temperature

def generate_temperatures(location, start_date, end_date):
    temperatures = []
    current_date = start_date
    while current_date <= end_date:
        day = random.randint(1, 31)
        month = random.randint(1, 12)
        if month in [1, 3, 5, 7, 8, 10, 12]:
            days_in_month = 31
        elif month == 2:
            days_in_month = 28
        else:
            days_in_month = 30
        date = datetime.combine(current_date.replace(day=day, month=month), datetime.min.time())
        temperature = random.randint(-20, 40)
        temperatures.append(Temperature(date, location, temperature))
        current_date += timedelta(days=1)
    return temperatures']",0,[0],[],True,0,0,0,

