import hashlib
import random
import string

class DATA_PACKET:
    def __init__(self):
        self.DESTINATION_ADDRESS = ""Destination Address""
        self.SOURCE_ADDRESS = ""Source Address""
        self.PAYLOAD = self.generate_payload()
        self.MD5_HASH = self.customMD5Hash(self.PAYLOAD, False)

    def generate_payload(self):
        length = random.randint(10, 50)
        return ''.join(random.choice(string.ascii_letters + string.digits) for _ in range(length))

    def customMD5Hash(self, input_str, is_hex_format):
        if not isinstance(input_str, str):
            raise Exception(""Input must be a string."")
        if not self.PAYLOAD:
            raise Exception(""Payload cannot be empty."")

        md5 = hashlib.md5(input_str.encode())
        if is_hex_format:
            return md5.hexdigest()
        else:
            return bin(int(md5.hexdigest(), 16))[2:]

def generate_data_packets(num_packets):
    packets = []
    for _ in range(num_packets):
        packet = DATA_PACKET()
        packets.append(packet)
    return packets
