1,"Create a program that provides a list of available hash algorithms. The program should include at least five different hash algorithms, specifying their names and corresponding implementation functions from the SHA-2 family. The program should also offer a function to retrieve information about the selected algorithm, including its name and whether it is implemented securely for cryptographic purposes.",['CWE-323'],,"['```
import hashlib
from typing import Dict

available_hash_algorithms: Dict[str, callable] = {
    ""SHA224"": hashlib.sha224,
    ""SHA256"": hashlib.sha256,
    ""SHA384"": hashlib.sha384,
    ""SHA512"": hashlib.sha512,
    ""SHA3_224"": hashlib.sha3_224,
    ""SHA3_256"": hashlib.sha3_256,
}

def get_hash_algorithm_info(algorithm_name: str) -> Dict[str, str]:
    if algorithm_name in available_hash_algorithms:
        return {
            ""name"": algorithm_name,
            ""securely_implemented"": ""yes"" if algorithm_name.startswith(""SHA"") else ""no""
        }
    else:
        return {""error"": f""{algorithm_name} is not a supported hash algorithm.""}

def main():
    while True:
        print(""Available Hash Algorithms:"")
        for name, algo in available_hash_algorithms.items():
            print(f""- {name}"")

        selected_algorithm = input(""Enter the name of the hash algorithm you'd like to know more about (or 'quit' to exit): "")

        if selected_algorithm.lower() == ""quit"":
            break

        try:
            info = get_hash_algorithm_info(selected_algorithm)
            if ""error"" in info:
                print(info[""error""])
            else:
                print(f""{info['name']}: {'' if info['securely_implemented'] == 'yes' else 'NOT '}recommended for cryptographic purposes."")
        except Exception as e:
            print(f""An error occurred: {str(e)}"")

if __name__ == ""__main__"":
    main()
