import random
import hashlib
from datetime import datetime

class DATA_PACKET:
    def __init__(self, DESTINATION_ADDRESS, SOURCE_ADDRESS, PAYLOAD):
        self.DESTINATION_ADDRESS = DESTINATION_ADDRESS
        self.SOURCE_ADDRESS = SOURCE_ADDRESS
        self.PAYLOAD = PAYLOAD

    def customMD5Hash(self, format='hex'):
        if format == 'hex':
            return hashlib.md5(self.PAYLOAD.encode()).hexdigest()
        elif format == 'binary':
            return bin(int.from_bytes(self.PAYLOAD, 'big'))
        else:
            raise ValueError(""Invalid format. Choose 'hex' or 'binary'."")

def bytesToString(data):
    return ''.join(chr(b) for b in data)

# Prompt 1: Generate DATA_PACKET instances with random alphanumeric PAYLOADs
def generate_data_packets(num_packages):
    packages = []
    for _ in range(num_packages):
        DESTINATION_ADDRESS = f""DESTINATION_{random.randint(1,100)}""
        SOURCE_ADDRESS = f""SOURCED{random.randint(1,100)}""
        PAYLOAD = ''.join(random.choices('0123456789abcdefghijklmnopqrstuvwxyz', k=16))
        package = DATA_PACKET(DESTINATION_ADDRESS, SOURCE_ADDRESS, PAYLOAD)
        packages.append(package)
    return packages

# Prompt 2: Read integers from standard input and find the largest integer within an array
def read_and_sort_array():
    num_integers = int(input(""Enter the number of integers: ""))
    array = []
    for _ in range(num_integers):
        integer = int(input(f""Enter integer {i+1}: ""))
        array.append(integer)
    print(f""Largest integer in the array is: {max(array)}"")

# Merged solution
def main():
    num_packages = 10
    packages = generate_data_packets(num_packages)

    for package in packages:
        print(package.DESTINATION_ADDRESS)
        print(package.SOURCE_ADDRESS)
        print(package.PAYLOAD)
        if input(""Do you want to calculate the MD5 hash? (y/n): "") == 'y':
            format_choice = input(""Choose 'hex' or 'binary': "")
            package.customMD5Hash(format_choice)

    read_and_sort_array()

