import hashlib
import random
import string

class DATA_PACKET:
    def __init__(self):
        self.DESTINATION_ADDRESS = 'DESTINATION_ADDRESS'
        self.SOURCE_ADDRESS = 'SOURCE_ADDRESS'
        self.PAYLOAD = ''.join(random.choices(string.ascii_letters + string.digits, k=16))
        self.customMD5Hash(self.PAYLOAD)

    def customMD5Hash(self, input_str, salt=None, isHexFormat=True):
        if not input_str or not salt:
            raise ValueError(""Input and salt cannot be null or empty."")

        m = hashlib.md5()
        m.update(salt.encode())
        m.update(input_str.encode())
        if isHexFormat:
            return m.hexdigest()
        else:
            return m.digest().decode()

    @staticmethod
    def bytesToString(data):
        return data.decode('utf-8') if isinstance(data, bytes) else str(data)

def generate_data_packets(num_packets):
    packets = []
    for _ in range(num_packets):
        packet = DATA_PACKET()
        packets.append(packet)

    return packets

# Example usage:
packets = generate_data_packets(5)
for packet in packets:
    print(f""Packet: {packet.DESTINATION_ADDRESS}, {packet.SOURCE_ADDRESS}, Payload={packet.PAYLOAD}, Hash={packet.customMD5Hash}"")
