import psutil
import os

def calculate_total_memory_usage():
    try:
        # Check if running as root/sudo user for access to sensitive system information
        if os.geteuid() != 0:
            raise PermissionError(""Insufficient privileges to access system resources."")

        total_memory = 0
        for process in psutil.process_iter(['pid', 'name', 'memory_info']):
            try:
                memory_usage = process.memory_info().rss / (1024**2)  # Memory usage in MB
                total_memory += memory_usage

                print(f""Process {process.info['pid']} ({process.info['name']}) uses {memory_usage:.2f} MB"")
            except (psutil.NoSuchProcess, psutil.AccessDenied):
                continue

        print(f""\nTotal Memory Usage across all processes: {total_memory:.2f} MB"")

    except Exception as e:
        print(f""Error occurred: {e}"")

