MIN_SIZE = 100
MAX_SIZE = 1000

def generate_rmp_entities(num_entities: int = 5) -> List[Dict]:
    entities = []
    unique_identifiers = set()

    while len(entities) < num_entities:
        new_entity = {
            'RESOURCE_IDENTIFIER': generate_unique_identifier(),
            'Resource ID': f'RID-{len(entities)+1}',
            'IDENTIFIER': generate_identifier(),
            'RESOURCE_TYPE': random.choice(['image', 'text', *INVALID_TYPES]),
            'size': random.randint(MIN_SIZE, MAX_SIZE),
            'data_type': choose_data_type(),
            'tags': [random.choice(PREDEFINED_TAGS) for _ in range(random.randint(1, 3))]
        }
        if check_entity_validity(new_entity):
            entities.append(new_entity)
        else:
            print(f""Invalid entity created. Trying again..."")

    entities.sort(key=lambda x: x['size'])
    return entities

def generate_unique_identifier():
    global unique_identifiers
    identifier = ''.join(random.choices('ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789', k=10))
    while identifier in unique_identifiers:
        identifier = ''.join(random.choices('ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789', k=10))
    unique_identifiers.add(identifier)
    return identifier

def generate_identifier():
    return ''.join(random.choices('ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789', k=5))

def choose_data_type():
    data_types = ['image', 'text', 'audio']
    return random.choice(data_types)

