import csv
import statistics

def compute_mean(csv_file, column_name, output_format='%f'):
    try:
        with open(csv_file, 'r') as file:
            reader = csv.DictReader(file)
            data = [float(row[column_name]) for row in reader if column_name in row and isinstance(float(row[column_name]), (int, float))]
            mean_value = statistics.mean(data) if data else None
            return output_format % mean_value
    except FileNotFoundError:
        return f""Error: File '{csv_file}' not found.""
    except KeyError:
        return f""Error: Column '{column_name}' not found in the CSV file.""
    except ValueError as e:
        return f""Error: Non-numeric data found in column '{column_name}': {e}.""
    except Exception as e:
        return f""An unexpected error occurred: {e}""
