void generate_random_crc_value(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    static unsigned int seed = 1; /* Random seed */
    unsigned int r = (seed = ++seed * 1103515245 + 12345) & 0xffffffff;
    pdu->crc_value = (uint32_t)(r >> 16) & 0x7fffffff;
}

uint8_t generate_random_rnti() {
    static unsigned int rand_seed = 0; /* Random seed */
    rand_seed ^= rand_seed >> 16;
    rand_seed *= static_cast<uint32_t>(RAND_MAX / (rand_seed + 1));
    return rand_seed % MAX_RNTI_SIZE + RNTI_MIN_VALUE;
}

uint8_t generate_random_rx_ue_information_tag() {
    static unsigned int rx_tag_seed = 0; 
    rx_tag_seed ^= rx_tag_seed >> 16;
    rx_tag_seed *= static_cast<uint32_t>(RAND_MAX / (rx_tag_seed + 1));
    return rx_tag_seed % MAX_RX_TAG_SIZE + RX_TAG_MIN_VALUE;
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T pdu;

    pdu.rnti = generate_random_rnti();
    pdu.rx_ue_information_tag = generate_random_rx_ue_information_tag();

    generate_random_crc_value(&pdu);

    return 0;
}
