import random
import struct
import hashlib
import logging

def generate_random_mac_frame(include_vlans=False, frame_length=64, destination=None, source=None, type_='00'):
    if destination is None:
        destination = [random.randint(0x00, 0xFF) for _ in range(6)]
    if source is None:
        source = [random.randint(0x00, 0xFF) for _ in range(6)]

    frame = b''

    # Add destination MAC address
    frame += struct.pack('BBB BBB', *destination)

    # Add source MAC address
    frame += struct.pack('BBB BBB', *source)

    # Add type field
    frame += struct.pack('BB', int(type_, 16))

    if include_vlans:
        # Add VLAN tags
        frame += struct.pack('HHLLL', 0x8100, random.randint(0x0001, 0xFFFF), random.getrandbits(16), random.getrandbits(16))

    # Calculate checksum
    def calculate_checksum(frame):
        return hashlib.crc32(frame)

    if type_ == '11':
        frame += struct.pack('I', calculate_checksum(frame))
    elif type_ == '06' or type_ == '08':
        frame += struct.pack('H', int(calculate_checksum(frame)))

    # Add padding to reach the desired length
    pad_len = frame_length - len(frame)
    if pad_len > 0:
        frame += b'\00' * pad_len

    return frame

def validate_mac_frame(frame, checksum=None):
    if not isinstance(frame, bytes):
        raise ValueError(""Invalid frame format"")

    # Check the type field
    if frame[14] >= 0x80 or (frame[12:14].hex() == 'c0' and frame[10].hex() in ['03', '08']):
        frame_type = frame[12:14].hex()
    else:
        frame_type = frame[12].hex()

    if not checksum:
        return True

    # Calculate the checksum
    calculated_checksum = calculate_checksum(frame)

    if type_='11':
        expected_checksum = struct.unpack('I', frame[18:22])[0]
    elif frame_type in ['06', '08']:
        expected_checksum = struct.unpack('H', frame[16:18])[0]

    return expected_checksum == checksum

def generate_multiple_frames(n, include_vlans=False):
    frames = []
    for _ in range(n):
        type_ = random.choice(['00', '11', '06', '08'])
        if type_ == '11':
            payload = struct.pack('I', random.getrandbits(32))
        elif type_ == '06' or type_ == '08':
            payload = struct.pack('H', random.getrandbits(16))
        else:
            payload = b'\00' * 4
        frames.append(generate_random_mac_frame(include_vlans, frame_length=64, destination=[0x00] * 6, source=[0x00] * 6, type_=type_))

    return frames

def generate_frames_with_diff_types(n):
    frames = []
    for _ in range(n):
        if random.random() < 0.5:
            type_ = '11'
            payload = struct.pack('I', random.getrandbits(32))
        else:
            type_ = '06'
            payload = struct.pack('H', random.getrandbits(16))
        frames.append(generate_random_mac_frame(include_vlans=False, frame_length=64, destination=[0x00] * 6, source=[0x00] * 6, type_=type_))

    return frames

def generate_frames_with_random_payload(n):
    frames = []
    for _ in range(n):
        type_ = random.choice(['00', '11', '06', '08'])
        payload_len = random.randint(1, 4)
        if type_ == '11':
            payload = struct.pack('I' * (payload_len // 4), *[random.getrandbits(32) for _ in range(payload_len)])
        elif type_ == '06' or type_ == '08':
            payload = struct.pack('H' * (payload_len // 2), *[random.getrandbits(16) for _ in range(payload_len)])
        else:
            payload = b'\00' * (payload_len * 4)
        frames.append(generate_random_mac_frame(include_vlans=False, frame_length=64, destination=[0x00] * 6, source=[0x00] * 6, type_=type_))

    return frames

def main():
    logging.basicConfig(level=logging.INFO)

    for frame in generate_frames_with_diff_types(5):
        logging.info(frame.hex())

if __name__ == ""__main__"":
