import os

def calculate_md5(file_path, block_size=4096, parallel=False):
    with open(file_path, 'rb') as file:
        md5_hash = hashlib.md5()

        if parallel and os.path.getsize(file_path) > block_size:
            chunk_size = min(block_size, os.path.getsize(file_path))

            with ThreadPoolExecutor() as executor:
                futures = {executor.submit(process_chunk, file, md5_hash, chunk_size): None}

                for future in as_completed(futures):
                    future.result()

        else:
            file.seek(0)
            while chunk := file.read(block_size):
                md5_hash.update(chunk)

    return md5_hash.hexdigest()

