from collections import deque

class Queue:
    def __init__(self):
        self.queue = deque()

    def enqueue(self, item):
        self.queue.append(item)

    def dequeue(self):
        if not self.is_empty():
            return self.queue.popleft()
        else:
            raise Exception(""Queue is empty. Dequeue operation failed."")

    def peek(self):
        if not self.is_empty():
            return self.queue[0]
        else:
            raise Exception(""Queue is empty. Peek operation failed."")

    def is_empty(self):
        return self.queue.empty()

    def size(self):
        return len(self.queue)

    def display(self):
        print(list(self.queue))
