import pickle
from pathlib import Path

class AdvancedGameSaveLoader:
    def __init__(self):
        self.game_scenarios = {}

    def load_game_save(self, file_name: str, scenario: str) -> dict:
        try:
            with open(file_name, 'rb') as file:
                game_state = pickle.load(file)
                if scenario in self.game_scenarios and scenario in game_state:
                    return game_state[scenario]
                else:
                    raise ValueError(""Invalid scenario or file"")
        except FileNotFoundError:
            print(f""File '{file_name}' not found."")
            return {}
        except pickle.UnpicklingError as e:
            print(f""Error deserializing data: {e}"")
            return {}

    def save_game_state(self, game_state: dict, file_name: str) -> None:
        try:
            with open(file_name, 'wb') as file:
                pickle.dump({scenario: state for scenario, state in game_state.items() if Path(scenario).exists()}, file)
        except FileNotFoundError:
            print(f""Error saving to file '{file_name}'."")
        except pickle.PicklingError as e:
            print(f""Error serializing data: {e}"")

    def add_game_scenario(self, scenario: str) -> None:
        self.game_scenarios[scenario] = None

