from dns.resolver import Resolver
import socket

class DNSHandler:
    def __init__(self):
        self.dns_cache = {}

    def update_dns(self, hostname):
        try:
            resolver = Resolver()
            answer = resolver.resolve(hostname, 'A')
            for rdata in answer:
                if rdata.address not in self.dns_cache.values():
                    self.dns_cache[hostname] = rdata.address
        except Exception as e:
            print(f""Error: {e}"")

    def add_or_update(self, key, value):
        if len(self.dns_cache) >= 50:
            print(""Dictionary is full. Consider resizing."")
        elif key in self.dns_cache:
            self.dns_cache[key] = value
        else:
            self.dns_cache[key] = value

    def get_dns_entry(self, hostname):
        return self.dns_cache.get(hostname)

dns_handler = DNSHandler()
dns_handler.update_dns('example.com')
dns_handler.add_or_update('key1', 'value1')
print(dns_handler.get_dns_entry('example.com'))
