from flask import Flask, request, jsonify
import json
import random
import string
import struct

app = Flask(__name__)
app.config['SECRET_KEY'] = 'super-secret-key'

# Function to generate random NFAPI CRC indication PDU arrays for network simulations
def generate_crc_indication_pdu_array(length):
    pdu_arrays = []
    for _ in range(length):
        pdu_array = [random.randint(0, 255) for _ in range(8)]
        crc_value = struct.pack('<I', sum(x << (i * 8) for i, x in enumerate(pdu_array)))
        pdu_arrays.append({'pdu_array': pdu_array, 'crc_value': crc_value.hex()})
    return pdu_arrays

# Route to generate random NFAPI CRC indication PDU arrays
@app.route('/generate_crc_indication_pdu_arrays', methods=['GET'])
def generate_crc_indication_pdu_arrays():
    length = int(request.args.get('length', 10))
    try:
        pdu_arrays = generate_crc_indication_pdu_array(length)
        return jsonify(pdu_arrays)
    except Exception as e:
        return {""error"": str(e)}

if __name__ == '__main__':
    app.run(debug=True)
