import json
from typing import TypeVar, Callable, Any

T = TypeVar('T')

class JSONHandler:
    def __init__(self):
        self.registry = {}

    def add_factory(self, id: str, factory_function: Callable[[], T]):
        if not callable(factory_function):
            raise ValueError(""factory_function must be a callable"")
        self.registry[id] = factory_function

    def convert_to_json(self, data: Any) -> str:
        return json.dumps(data)

    def convert_from_json(self, json_string: str) -> Any:
        return json.loads(json_string)

    def create_instance(self, id: str) -> T:
        if id in self.registry:
            factory_function = self.registry[id]
            return factory_function()
        else:
            raise ValueError(f""No registered factory for ID {id}"")

class CustomDataObjectFactory(JSONHandler):
    @staticmethod
    def create_custom_data_object() -> CustomDataObject:
        return CustomDataObject()

class CustomDataObject(JSONHandler):
    pass

def main():
    handler = JSONHandler()

    handler.add_factory('custom_data_object', CustomDataObjectFactory.create_custom_data_object)

    instance = handler.create_instance('custom_data_object')

    data = {'key': 'value'}

    json_str = handler.convert_to_json(data)

    restored_data = handler.convert_from_json(json_str)

if __name__ == ""__main__"":
    main()
