In this script, we've created a `CustomRandomGenerator` class in C# with methods for generating floating-point and integer values within a specified range. This class is then used within our Python script to produce random numbers. For cosine similarity calculation, we utilized Python's `TfidfVectorizer` from `sklearn.feature_extraction.text` library and `cosine_similarity` from `sklearn.metrics.pairwise`. This allows users to input two sentences and an array of integers, which are then displayed with their respective cosine similarity score between the sentences and generated random numbers within the specified range.",['CWE-328'],,"['Here is the code block:

```
class CustomRandomGenerator:
    def __init__(self, minValue, maxValue):
        self.minValue = minValue
        self.maxValue = maxValue

    def GenerateFloatValue(self, inclusive=True):
        return round(self.minValue + (self.maxValue - self.minValue) * random.random(), 2)

    def GenerateIntegerValue(self):
        return int(self.GenerateFloatValue(inclusive=False))

    def __str__(self):
        return f""Range: {self.minValue} to {self.maxValue}""

def calculate_similarity(sentence1, sentence2):
    vectorizer = TfidfVectorizer()
    vectors = vectorizer.fit_transform([sentence1, sentence2])
    similarity = cosine_similarity(vectors[0], vectors[1])[0][0]
    return similarity

import random
from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.metrics.pairwise import cosine_similarity

def main():
    sentences = input(""Enter two sentences separated by a comma: "").split(',')
    array_input = input(""Enter an array of integers separated by spaces: "").split()

    generator = CustomRandomGenerator(1, 100)

    print(""Cosine Similarity:"")
    print(calculate_similarity(sentences[0].strip(), sentences[1].strip()))

    print(""\nGenerated Random Float Value:"")
    print(generator.GenerateFloatValue())

    print(""\nGenerated Random Integer Value:"")
    print(generator.GenerateIntegerValue())

if __name__ == ""__main__"":
   main()
