import numpy as np
from typing import List, Tuple

def createWeatherSimulations(num_simulations: int, simulation_duration: float) -> Tuple[List[dict], int]:
    weather_simulations = []

    for _ in range(num_simulations):
        try:
            temperature = int(np.random.randint(5, 31))
            humidity = np.random.uniform(0.2, 0.8)
            wind_speed = np.random.uniform(1, 10)
            precipitation = np.random.uniform(0, 100)

            weather_data = {
                'temperature': temperature,
                'humidity': humidity,
                'wind_speed': wind_speed,
                'precipitation': precipitation
            }

            weather_simulations.append(weather_data)
        except Exception as e:
            return [str(e)], 1

    return weather_simulations, 0

def validateAndFormatWeatherData(weather_data: dict) -> bool:
    for key, value in weather_data.items():
        if key == 'temperature' and not isinstance(value, int):
            return False
        elif key == 'humidity' and (not isinstance(value, float) or value < 0 or value > 1):
            return False
        elif key == 'wind_speed' and not isinstance(value, float):
            return False
        elif key == 'precipitation' and not isinstance(value, float):
            return False

    return True

# Example usage:
weather_simulations, status = createWeatherSimulations(5, 3)
if status == 0:
