def complex_replace(numbers, threshold, operation):
    if not all(isinstance(x, int) and -10 <= x <= 10 for x in numbers):
        return None

    if not isinstance(threshold, int) or not -10 <= threshold <= 10:
        return None

    if not (isinstance(operation, str) or callable(operation)):
        return None

    result = []
    for i, num in enumerate(numbers):
        if num < threshold:
            result.append(i)
        elif num > threshold:
            if 5 <= num <= 10:
                result.append(num)
            else:
                result.append(""Invalid"")
        else:
            try:
                result.append(eval(f""{num} {operation}""))
            except Exception as e:
                print(f""Error: {e}"")
                result.append(""Invalid"")

    return result
