def validateData(*args):
    error_messages = []
    for arg in args:
        if not isinstance(arg, dict) or 'id' not in arg or 'value' not in arg:
            error_messages.append(f""Invalid data format: {arg}"")
        elif not isinstance(arg['value'], (int, float)):
            error_messages.append(f""Value must be numeric: {arg['value']}"")
    if error_messages:
