    else:
        return None

def optimizeData(data):
    optimized_data = []
    for record in data:
        if 'id' not in record or 'value' not in record:
            continue
        value = record['value']
        if value < 0.5:
            value *= 2
        elif value > 1.5:
            value /= 3
        optimized_data.append({'id': record['id'], 'value': value})
    return optimized_data

def validateAndOptimizeData(*args):
