import random
import numpy as np

def createWeatherSimulations(num_simulations, simulation_duration):
    try:
        # Allocate memory for the array of weather simulation datasets
        weather_data = np.zeros((num_simulations, 4), dtype=[('temperature', float), ('humidity', int), ('wind_speed', float), ('precipitation', int)])

        for i in range(num_simulations):
            temperature = validateAndFormatWeatherData(random.uniform(5, 30))
            humidity = validateAndFormatWeatherData(random.randint(20, 80))
            wind_speed = validateAndFormatWeatherData(random.uniform(0, 10))
            precipitation = validateAndFormatWeatherData(random.randint(0, 100))

            weather_data[i] = (temperature, humidity, wind_speed, precipitation)

        return 0

    except Exception as e:
        print(f""An error occurred: {e}"")
        return -1


def validateAndFormatWeatherData(value):
    if isinstance(value, float):
        if value < 5 or value > 30:
            raise ValueError(""Invalid temperature range. Please adjust."")
        return round(value, 2)
    elif isinstance(value, int):
        if value < 20 or value > 80:
            raise ValueError(""Invalid humidity range. Please adjust."")
        return value
    elif isinstance(value, float) and 0 <= value <= 10:
        return round(value, 1)
    elif isinstance(value, int) and 0 <= value <= 100:
        return value
    else:
        raise ValueError(""Invalid data type. Please adjust."")
