class DATA_PACKET:
    def __init__(self, source_address, destination_address, payload_length, payload_data):
        self.source_address = source_address
        self.destination_address = destination_address
        self.payload_length = payload_length
        self.payload_data = payload_data

    @staticmethod
    def customMD5Hash(payload_data):
        import hashlib
        md5_hash = hashlib.md5()
        md5_hash.update(payload_data)
        return md5_hash.hexdigest()

    @staticmethod
    def bytesToString(byte_array):
        return ''.join([chr(b) for b in byte_array])

