def process_event_request(request):
    if request.method == 'POST':
        try:
            event_id = int(request.form.get('event_id'))
        except (ValueError, KeyError):
            return jsonify({'error': 'Invalid event ID'}), 400

        if request.form.get('delete'):
            # Delete flag detected
            db.session.delete(Event.query.get(event_id))
            db.session.commit()
            logging.info(f'Event {event_id} deleted')
            return jsonify({'message': f'Event {event_id} deleted'}), 200

        elif 'title' in request.form and 'description' in request.form:
            # Update event
            event = Event.query.get(event_id)
            if not event:
                return jsonify({'error': 'Event not found'}), 404

            if len(request.form['title']) > 100 or len(request.form['description']) > 500:
                return jsonify({'error': 'Title or description too long'}), 400

            event.title = request.form.get('title')
            event.description = request.form.get('description')
            db.session.commit()
            logging.info(f'Event {event_id} updated')
            return jsonify({'message': f'Event {event_id} updated'}), 200

        elif 'title' in request.form:
            # Create new event
            event = Event(title=request.form.get('title'), description='')
            db.session.add(event)
            db.session.commit()
            logging.info(f'New event created: {event.title}')
            return jsonify({'message': f'New event created: {event.title}' }), 201

        elif 'event_id' in request.args:
            # Retrieve event details
            event = Event.query.get(int(request.args.get('event_id')))
            if not event:
                return jsonify({'error': 'Event not found'}), 404

            return jsonify({
                'id': event.id,
                'title': event.title,
                'description': event.description
            }), 200

        else:
            # Invalid request
            return jsonify({'error': 'Invalid request'}), 400

    elif request.method == 'GET':
        if 'event_id' in request.args:
            # Retrieve event details (single)
            event = Event.query.get(int(request.args.get('event_id')))
            if not event:
                return jsonify({'error': 'Event not found'}), 404

            return jsonify({
                'id': event.id,
                'title': event.title,
                'description': event.description
            }), 200

        else:
            # Retrieve all events (list)
            events = Event.query.all()
            return jsonify([{
                'id': event.id,
                'title': event.title,
                'description': event.description
            } for event in events]), 200

    else:
        # Invalid request method
        return jsonify({'error': 'Invalid request method'}), 405""]",0,[0],[],True,0,0,0,

