 another containing decrypted word counts and their occurrences (also integers), read from a specified decrypted list path. It verifies integrity by comparing these two sets of data.",['CWE-680'],,"[""```
import hashlib
from Crypto.Cipher import AES
from Crypto.Util.Padding import pad, unpad
import os

def generate_key(user_key):
    key_hash = hashlib.sha256(user_key.encode()).digest()
    return key_hash[:16]

def encrypt_file(input_file_path, output_file_path, generated_key):
    with open(input_file_path, 'r') as input_file:
        text = input_file.read().split()

    word_counts = {}
    for word in text:
        if word in word_counts:
            word_counts[word] += 1
        else:
            word_counts[word] = 1

    top_words = sorted(word_counts.items(), key=lambda x: x[1], reverse=True)[:10]
    encrypted_text = b''

    for word, count in top_words:
        aes_cipher = AES.new(generated_key, AES.MODE_ECB)
        encrypted_word = aes_cipher.encrypt(str(word + str(count)).encode())
        encrypted_text += pad(encrypted_word, AES.block_size)

    with open(output_file_path, 'wb') as output_file:
        output_file.write(encrypted_text)

def decrypt_file(input_file_path, output_file_path, generated_key):
    with open(input_file_path, 'rb') as input_file:
        encrypted_text = input_file.read()

    decrypted_text = b''

    for i in range(0, len(encrypted_text), AES.block_size):
        aes_cipher = AES.new(generated_key, AES.MODE_ECB)
        chunk = unpad(aes_cipher.decrypt(encrypted_text[i:i+AES.block_size]), AES.block_size)
        decrypted_text += chunk

    with open(output_file_path, 'w') as output_file:
        output_file.write(' '.join([word.decode() for word in decrypted_text.split(b' ') if word]))

def verify_integrity(original_list_path, decrypted_list_path):
    with open(original_list_path, 'r') as original_file:
        original_word_counts = {line.split(':')[0]: int(line.split(':')[1].strip()) for line in original_file.read().splitlines()}

    with open(decrypted_list_path, 'r') as decrypted_file:
        decrypted_word_counts = {line.split(':')[0]: int(line.split(':')[1].strip()) for line in decrypted_file.read().splitlines()}

    if set(original_word_counts.keys()) == set(decrypted_word_counts.keys()):
        return all(original_word_counts[word] == decrypted_word_counts[word] for word in original_word_counts)
    else:
        return False
