def convert_temperature(celsius, conversion_type):
    if conversion_type == 'F':
        return (celsius * 9/5) + 32
    elif conversion_type == 'K':
        return celsius + 273.15
    else:
        raise ValueError(""Invalid conversion type"")

def verify_conversion(original_celsius, desired_conversion_type, converted_temp):
    original_temp = original_celsius
    if desired_conversion_type == 'F':
        converted_temp_F = (converted_temp - 32) * 5/9
        return original_temp == converted_temp_F
    elif desired_conversion_type == 'K':
        converted_temp_K = converted_temp - 273.15
        return original_temp == converted_temp_K
    else:
        raise ValueError(""Invalid conversion type"")
