class EnhancedCustomRandomGenerator:
    def __init__(self, min_value: int, max_value: int):
        self.min_value = min_value
        self.max_value = max_value

    def GenerateFloatValue(self, inclusive: bool) -> float:
        if inclusive:
            return random.uniform(self.min_value, self.max_value)
        else:
            return random.randint(self.min_value, self.max_value)

    def GenerateIntegerValue(self, inclusive: bool) -> int:
        if inclusive:
            return random.randint(self.min_value, self.max_value)
        else:
            return random.randrange(self.min_value, self.max_value + 1)

    def generate_random_values(self, count: int, func: FuncGenerator[any], func_name: str) -> list[any]:
