        # implementation left out for brevity
        pass

    def generate_random_data_entries(self, count: int) -> list[DATA_PACKET_T]:
        random_packets = []
        for _ in range(count):
            source_address = self.GenerateIntegerValue(True)
            destination_address = self.GenerateIntegerValue(True)
            payload_length = self.GenerateIntegerValue(True)
            payload_data = self.GenerateFloatValue(False)
            packet = DATA_PACKET_T(source_address, destination_address, payload_length, payload_data)
            random_packets.append(packet)
        return random_packets

