import uuid
import random

def generate_nfc_tags(num_tags):
    nfc_tags = []
    for _ in range(num_tags):
        id = str(uuid.uuid4()).upper().replace('-', '')
        major = ''.join(random.choices('0123456789abcdef', k=8)).upper()
        minor = random.randint(0, 100)
        transactions = random.randint(1, 1000)
        nfc_tag = {'id': id, 'major': major, 'minor': minor, 'transactions': transactions}
        nfc_tags.append(nfc_tag)
    return nfc_tags""]",414,[0],[],True,0,0,0,

