import hashlib
import os

class FileHandler:
    def __init__(self):
        self.file_path = None

    def set_file_path(self, file_path):
        self.file_path = file_path

    def generate_md5_hash(self, input_string):
        return hashlib.md5(input_string.encode()).hexdigest()

    def read_and_sort_file(self):
        if not self.file_path:
            raise ValueError(""File path not set."")

        try:
            with open(self.file_path, 'r') as file:
                lines = sorted(file.readlines(), key=str.strip)

            sequence_number = lines[-1].strip().split(':')[-1] if lines else None

            return sequence_number
        except FileNotFoundError:
            raise FileNotFoundError(f""The specified file {self.file_path} was not found."")

# Example usage:

file_handler = FileHandler()
file_handler.set_file_path('example.txt')
