import hashlib
import os

class TextAnalyzer:
    def __init__(self, file_path):
        self.file_path = file_path

    def read_file(self):
        try:
            with open(self.file_path, 'r') as file:
                return file.read()
        except FileNotFoundError:
            print(f""File not found: {self.file_path}"")
            return None
        except Exception as e:
            print(f""Error reading the file: {e}"")
            return None

    def calculate_sha256_hash(self, text):
        try:
            hash_object = hashlib.sha256(text.encode())
            return hash_object.hexdigest()
        except Exception as e:
            print(f""Error calculating SHA-256 hash: {e}"")
            return None

    def find_longest_word(self, text):
        words = text.split()
        longest_word = max(words, key=len)
        return longest_word

    def analyze_file(self):
        text = self.read_file()
        if text is not None:
            sha256_hash = self.calculate_sha256_hash(text)
            longest_word = self.find_longest_word(text)

            print(f""SHA-256 Hash: {sha256_hash}"")
            print(f""Longest Word: {longest_word}"")

if __name__ == ""__main__"":
    analyzer = TextAnalyzer('example.txt')
    analyzer.analyze_file()
