from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes

class SecureJSONParser:
    def __init__(self, encryption_key):
        self.encryption_key = encryption_key.encode()
        self.cipher = Cipher(algorithms.AES(self.encryption_key), modes.ECB(), backend=default_backend())
        self.encryptor = self.cipher.encryptor()

    def parse_json_and_encrypt(self, json_data):
        try:
            data = json.loads(json_data)
            encrypted_data = {}
            for key, value in data.items():
                if isinstance(value, str) and len(value) > 10:  # assuming sensitive information has more than 10 characters
                    encrypted_value = self.encryptor.update(value.encode()) + self.encryptor.finalize()
                    encrypted_data[key] = base64.b64encode(encrypted_value).decode()
                else:
                    encrypted_data[key] = value
            return json.dumps(encrypted_data)
        except Exception as e:
            print(f""Error parsing JSON: {str(e)}"")
            return None

    def decrypt_and_store(self, encrypted_json):
        try:
            encrypted_data = json.loads(encrypted_json)
            for key, value in encrypted_data.items():
                if isinstance(value, str) and len(value) > 10:
                    decrypted_value = self.cipher.decryptor().update(base64.b64decode(value.encode())) + self.cipher.decryptor().finalize()
                    encrypted_data[key] = decrypted_value.decode()
            return json.dumps(encrypted_data)
        except Exception as e:
            print(f""Error decrypting JSON: {str(e)}"")
            return None

    def store_in_database(self, decrypted_json):
