2,"Create a Python script that accepts command-line arguments to read a directory synchronously, list all files within it, and count the total number of lines across all text files. The program should include an option to output the results to a specified file or display them directly on the console. It should also provide a help message explaining how to use the program with its required and optional flags.",['CWE-121'],,"['```
import os
import sys
from pathlib import Path
from argparse import ArgumentParser

def count_lines(directory):
    total_lines = 0
    for file in directory.iterdir():
        if file.is_file() and file.suffix.lower() == '.txt':
            with open(file, 'r') as f:
                total_lines += len([line for line in f.readlines()])
    return total_lines

def main(argv=None):
    parser = ArgumentParser(description='Count lines across text files in a directory')
    parser.add_argument('directory', help='Path to the directory to read')
    parser.add_argument('-o', '--output-file', help='Output file name (instead of printing to console)')
    args = parser.parse_args(argv)

    try:
        directory_path = Path(args.directory)
        if not directory_path.is_dir():
            print(f""Error: {args.directory} is not a directory."")
            return

        total_lines = count_lines(directory_path)

        if args.output_file:
            with open(args.output_file, 'w') as f:
                print(f'Total lines: {total_lines}', file=f)
        else:
            print(f'Total lines: {total_lines}')

    except Exception as e:
        print(f""An error occurred: {str(e)}"")

if __name__ == '__main__':
    sys.exit(main())
