import random
import hashlib
import logging
from typing import Dict, List

logging.basicConfig(level=logging.INFO)

class MacFrame:
    def __init__(self, src_mac: str, dst_mac: str, frame_type: int, data: bytes):
        self.src_mac = src_mac
        self.dst_mac = dst_mac
        self.frame_type = frame_type
        self.data = data

def generate_random_mac_frame(frame_length: int, include_vlans: bool = False) -> MacFrame:
    frame = b''

    # Add VLAN tags if required
    if include_vlans:
        vlan_tag = random.randint(0x0001, 0xFFFF).to_bytes(2, 'big')
        frame += vlan_tag

    # Generate a random MAC frame with the specified length
    for _ in range(frame_length):
        frame += bytes([random.randint(0x00, 0xFF)])

    return MacFrame(*get_random_macs(), frame_type=random.randint(0x0000, 0xFFFF), data=frame)

def validate_mac_frame(mac_frame: MacFrame) -> bool:
    # Calculate the checksum using a specified algorithm
    checksum = hashlib.md5(mac_frame.data).hexdigest()

    # Verify the checksum
    if not mac_frame.data.startswith(checksum.encode()):
        return False

    return True

def generate_multiple_frames(frame_count: int, frame_length: int, include_vlans: bool = False) -> List[MacFrame]:
    frames = []
    for _ in range(frame_count):
        frames.append(generate_random_mac_frame(frame_length, include_vlans))

    return frames

def get_random_macs() -> (str, str):
    macs = [f'{random.randint(0x00, 0xFF):02X}{random.randint(0x00, 0xFF):02X}{random.randint(0x00, 0xFF):02X}{random.randint(0x00, 0xFF):02X}{random.randint(0x00, 0xFF):02X}{random.randint(0x00, 0xFF):02X}' for _ in range(2)]
    return macs

if __name__ == ""__main__"":
    logging.info(""Generating frames..."")
    frames = generate_multiple_frames(5, 100)
    for frame in frames:
        if not validate_mac_frame(frame):
            logging.error(f""Invalid MAC frame: {frame}"")
        else:
            logging.info(f""Valid MAC frame: {frame}"")
