def find_median(n, arr):
    if not isinstance(n, int) or not all(isinstance(x, (int, float)) for x in arr):
        return -1
    if n != len(arr):
        return -1
    sorted_arr = sorted(arr)
    median_index = len(sorted_arr) // 2
    if len(sorted_arr) % 2 == 0:
        return (sorted_arr[median_index] + sorted_arr[median_index-1]) / 2
    else:
        return sorted_arr[median_index]
