import random
import os

def generate_and_save_randomized_lists(integers, list_count):
    output_dir = ""randomized_lists""
    if not os.path.exists(output_dir):
        try:
            os.mkdir(output_dir)
        except OSError as e:
            print(f""Failed to create directory {output_dir}: {e}"")
            return None

    for i in range(list_count):
        randomized_list = [str(random.uniform(0, 100)) for _ in range(5)]
        file_path = f""{output_dir}/output_list_{i}.txt""
        try:
            with open(file_path, 'w') as f:
                f.write(', '.join(randomized_list))
        except OSError as e:
            print(f""Failed to write to file {file_path}: {e}"")
            return None

    return output_dir
